	/**
	 * Default Constructor
	 */
    public CoverageService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new CoverageEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(CoverageRepository.class) );
		this.validator		= applicationContext.getBean(CoverageValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		Coverage
	 */
		public Coverage createCoverage( CreateCoverageCommand command ) {

		Coverage entity = new Coverage();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setCoverageId( command.getCoverageId() );
            entity.setMemberId( command.getMemberId() );
            entity.setGroupNumber( command.getGroupNumber() );
            entity.setEffectiveDate( command.getEffectiveDate() );
            entity.setEndDate( command.getEndDate() );
            entity.setCoverageType( command.getCoverageType() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of Coverage {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateCoverageCommand
	 * @return		Coverage
	 */
	public Coverage updateCoverage( UpdateCoverageCommand command ) {

		Coverage entity = new Coverage();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setCoverageId( command.getCoverageId() );
            entity.setMemberId( command.getMemberId() );
            entity.setGroupNumber( command.getGroupNumber() );
            entity.setEffectiveDate( command.getEffectiveDate() );
            entity.setEndDate( command.getEndDate() );
            entity.setPatient( command.getPatient() );
            entity.setPlan( command.getPlan() );
            entity.setClaims( command.getClaims() );
            entity.setAuthorizations( command.getAuthorizations() );
            entity.setCoverageType( command.getCoverageType() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of Coverage {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteCoverageCommand
	 */
	public void delete( DeleteCoverageCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getCoverageId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of Coverage {0} ", id );

	}

	/**
	 * Method to retrieve the Coverage via CoverageFetchOneSummary
	 * @param 	summary CoverageFetchOneSummary
	 * @return 	CoverageFetchOneResponse
	 */
	public Coverage getCoverage( CoverageFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "CoverageFetchOneSummary arg cannot be null" );

		Coverage entity = null;
		UUID id = summary.getCoverageId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a Coverage using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all Coverages
	 *
	 * @return 	List<Coverage>
	 */
    public List<Coverage> getAllCoverage() {
		List<Coverage> list = projector.findAll( new FindAllCoverageQuery() );
		return list;
	}

	/**
	 * assign Patient on Coverage
	 * @param		command AssignPatientToCoverageCommand
	 */
	public void assignPatient( AssignPatientToCoverageCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignPatient(command.getCoverageId(), command.getAssignment());

	}

